def norm_phone(s):
    d = ''.join(c for c in s if c.isdigit())

    if len(d) == 10:
        d = '7' + d
    elif len(d) == 11 and d.startswith('8'):
        d = '7' + d[1:]

    return d if len(d) == 11 else None
