def find_gaps(sorted_ints):
    if not sorted_ints:
        return []

    gaps = []
    for i in range(len(sorted_ints) - 1):
        start = sorted_ints[i]
        end = sorted_ints[i + 1]
        if end > start:
            gaps.extend(range(start + 1, end))

    return gaps
```

